sop:
@f1 w.request.filler text="sister is house-sitting this week"
@r1 w.request.request act=make mood=do words="make her a new document called Cat care that says \"Feed Milo twice a day and keep the balcony door shut.\"" predicate=make
@r1.t w.request.target request=$r1 family=text mode=new determiner=indefinite family_words=document
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=text.title value="Cat care" operator=eq phase=result key_words=called
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=text.content value="Feed Milo twice a day and keep the balcony door shut." operator=eq phase=result key_words=says

@r1 w.request.request act=make mood=do predicate=create
@r1.u1 w.request.unread request=$r1 text="If there isn't a document for it yet" note=document.createIfAbsent
@r1.t w.request.target request=$r1 family=text mode=new determiner=indefinite family_words=document
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=text.title value="Door code" operator=eq phase=result key_words=named
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=text.content value="Front door 4711, gate 0815." operator=eq phase=result key_words=containing

@r1 w.request.request act=change mood=do predicate=add
@r1.t w.request.target request=$r1 family=block mode=existing determiner=definite fill=written name=Intro
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=block.id value=Intro operator=eq phase=selector
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=block.mark value=link words=hyperlink operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=block.text value="the full schedule" operator=eq phase=selector
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=block.attrs value="https://example.com/schedule" operator=eq phase=result

@f1 w.request.filler text="readers can't find the sources, so"
@f2 w.request.filler text=please
@r1 w.request.request act=change mood=do words="in the Background paragraph please link \"the original study\" to https://journal.example.org/study-17" predicate=link
@r1.t w.request.target request=$r1 family=block mode=existing determiner=definite fill=written name=Background family_words=paragraph
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=block.id value=Background operator=eq phase=selector
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=block.mark value=link operator=eq phase=result
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=block.text value="the original study" operator=eq phase=selector
@r1.c4 w.request.constraint request=$r1 on=attribute attribute=block.attrs value="https://journal.example.org/study-17" operator=eq phase=result

@r1 w.request.request act=change mood=do predicate=link
@r1.t w.request.target request=$r1 family=block mode=existing determiner=definite fill=context
@r1.l1 w.request.lookup request=$r1 target=$r1.t key=thing from=page
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=block.mark value=link operator=eq phase=result
@r1.c2 w.request.constraint request=$r1 on=attribute attribute=block.text value=pricing operator=eq phase=selector
@r1.c3 w.request.constraint request=$r1 on=attribute attribute=block.attrs value="example.com/prices" operator=eq phase=result

@f3 w.request.filler text="before I lose the thought"
@f1 w.request.filler text=just
@f2 w.request.filler text=please
@r1 w.request.request act=make mood=do words="a fresh doc with just this line, please: \"Call the bank about the new card on Monday.\""
@r1.t w.request.target request=$r1 family=text mode=new determiner=indefinite description=fresh family_words=doc
@r1.c1 w.request.constraint request=$r1 on=attribute attribute=text.content value="Call the bank about the new card on Monday." operator=eq phase=result key_words=line
